  Lemma auxw_ok : forall i ty v,
    (0 <= i <= 9) ->
    nth (Z.to_nat (2 * i)) (auxv_words ph (at_random_ptr sp argv envp) uid hw) (Z_to_bv 64 0) = Z_to_bv 64 ty ->
